int32_t rf_r4_t5d10_fp32_predict(const float *features, int32_t features_length) {

        int32_t votes[3] = {0,};
        int32_t _class = -1;

        _class = rf_r4_t5d10_fp32_tree_0(features, features_length); votes[_class] += 1;
    _class = rf_r4_t5d10_fp32_tree_1(features, features_length); votes[_class] += 1;
    _class = rf_r4_t5d10_fp32_tree_2(features, features_length); votes[_class] += 1;
    _class = rf_r4_t5d10_fp32_tree_3(features, features_length); votes[_class] += 1;
    _class = rf_r4_t5d10_fp32_tree_4(features, features_length); votes[_class] += 1;
    
        int32_t most_voted_class = -1;
        int32_t most_voted_votes = 0;
        for (int32_t i=0; i<3; i++) {

            if (votes[i] > most_voted_votes) {
                most_voted_class = i;
                most_voted_votes = votes[i];
            }
        }
        return most_voted_class;
    }
    

int rf_r4_t5d10_fp32_predict_proba(const float *features, int32_t features_length, float *out, int out_length) {

        int32_t _class = -1;

        for (int i=0; i<out_length; i++) {
            out[i] = 0.0f;
        }

        _class = rf_r4_t5d10_fp32_tree_0(features, features_length); out[_class] += 1.0f;
    _class = rf_r4_t5d10_fp32_tree_1(features, features_length); out[_class] += 1.0f;
    _class = rf_r4_t5d10_fp32_tree_2(features, features_length); out[_class] += 1.0f;
    _class = rf_r4_t5d10_fp32_tree_3(features, features_length); out[_class] += 1.0f;
    _class = rf_r4_t5d10_fp32_tree_4(features, features_length); out[_class] += 1.0f;
    
        // compute mean
        for (int i=0; i<out_length; i++) {
            out[i] = out[i] / 5;
        }
        return 0;
    }
    